TriggerOraclev10g.body:
DECLARE
  v_anteriores CLOB;
  v_nuevos     CLOB;
BEGIN
  IF UPDATING OR DELETING THEN
    SELECT JSON_OBJECT('ID_DEVOLUCION' VALUE :OLD.ID_DEVOLUCION, 'ID_PRESTAMO' VALUE :OLD.ID_PRESTAMO, 'FECHA_DEVOLUCION_REAL' VALUE :OLD.FECHA_DEVOLUCION_REAL, 'A_TIEMPO' VALUE :OLD.A_TIEMPO, 'DIAS_RETRASO' VALUE :OLD.DIAS_RETRASO, 'OBSERVACIONES' VALUE :OLD.OBSERVACIONES, 'ID_BIBLIOTECARIO' VALUE :OLD.ID_BIBLIOTECARIO) INTO v_anteriores FROM dual;
  END IF;
  IF INSERTING OR UPDATING THEN
    SELECT JSON_OBJECT('ID_DEVOLUCION' VALUE :NEW.ID_DEVOLUCION, 'ID_PRESTAMO' VALUE :NEW.ID_PRESTAMO, 'FECHA_DEVOLUCION_REAL' VALUE :NEW.FECHA_DEVOLUCION_REAL, 'A_TIEMPO' VALUE :NEW.A_TIEMPO, 'DIAS_RETRASO' VALUE :NEW.DIAS_RETRASO, 'OBSERVACIONES' VALUE :NEW.OBSERVACIONES, 'ID_BIBLIOTECARIO' VALUE :NEW.ID_BIBLIOTECARIO) INTO v_nuevos FROM dual;
  END IF;
  SP_REGISTRAR_BITACORA(
    'DEVOLUCION',
    CASE WHEN INSERTING THEN 'INSERT' WHEN UPDATING THEN 'UPDATE' ELSE 'DELETE' END,
    NVL(:NEW.ID_DEVOLUCION, :OLD.ID_DEVOLUCION),
    v_anteriores,
    v_nuevos
  );
END;
